    {
      "goal": "Define qualification rubric, ranking priority (Seattle/PNW presence > climate/circular fit > recent activity), and the final output template to be used across all research tracks",
      "tool_name": "reasoning",
      "depends_on": []
    },
    {
      "goal": "Research and compile candidates: Seattle/PNW-based seed VCs & micro-VCs with climate/sustainability/circular theses; capture evidence links, stage, and recent activity",
      "tool_name": "spawn_sub_agent",
      "depends_on": [0]
    },
    {
      "goal": "Research and compile candidates: Seattle/PNW-based angel investors (individuals) known for climate/sustainability/circular investing; include proof of activity (recent deals/posts) and source links",
      "tool_name": "spawn_sub_agent",
      "depends_on": [0]
    },
    {
      "goal": "Research and compile candidates: angel syndicates/communities with Seattle/PNW footprint (or strong PNW deal flow) that back climate/sustainability/circular startups; include how founders can engage",
      "tool_name": "spawn_sub_agent",
      "depends_on": [0]
    },
    {
      "goal": "Research and compile candidates: non-PNW climate seed funds/angels that demonstrably invest in the Pacific Northwest (partner in Seattle, frequent PNW deals, or explicit geo openness) with evidence links",
